import collections

def solve_n(n):
    all_ones = (1 << (n*n)) - 1
    good_states = {all_ones}
    queue = collections.deque([all_ones])

    while queue:
        curr = queue.popleft()
        # Inverse Rule 1: 4 ones -> 3 ones
        for r in range(n-1):
            for c in range(n-1):
                indices = [r*n + c, r*n + c+1, (r+1)*n + c, (r+1)*n + c+1]
                ones = [ (curr >> i) & 1 for i in indices ]
                if sum(ones) == 4:
                    for i in range(4):
                        prev_state = curr
                        prev_state &= ~(1 << indices[i])
                        if prev_state not in good_states:
                            good_states.add(prev_state)
                            queue.append(prev_state)
        # Inverse Rule 2: 2 ones -> flip
        for r in range(n-1):
            for c in range(n-1):
                indices = [r*n + c, r*n + c+1, (r+1)*n + c, (r+1)*n + c+1]
                ones = [ (curr >> i) & 1 for i in indices ]
                if sum(ones) == 2:
                    new_state = curr
                    for i in indices:
                        if (curr >> i) & 1:
                            new_state &= ~(1 << i)
                        else:
                            new_state |= (1 << i)
                    if new_state not in good_states:
                        good_states.add(new_state)
                        queue.append(new_state)

    max_bad_k = -1
    for state in range(1 << (n*n)):
        if state not in good_states:
            k = bin(state).count('1')
            if k > max_bad_k:
                max_bad_k = k

    return max_bad_k + 1

